import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import type { PrimitiveProps } from "../primitives";

const GreenStatic: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const t = frame / fps;

  // Grain re-seeds every 2 frames and cycles through 48 seeds, so it loops for any length.
  const seed = Math.floor(frame / 2) % 48;
  // Slow breathing of the central glow (~8s period).
  const breathe = 0.5 + 0.5 * Math.sin((t * 2 * Math.PI) / 8);
  // Scanlines drift downward continuously; modulo keeps the pattern seamless.
  const scanOffset = (t * 12) % 6;
  // A soft, wide band rolls down the screen every 10s, like a weak analog signal.
  const rollY = ((t / 10) % 1) * 2400 - 240;

  return (
    <AbsoluteFill style={{ backgroundColor: "#0F4D24" }}>
      <AbsoluteFill
        style={{
          background: "linear-gradient(180deg, #0B3D1C 0%, #1E7A3C 50%, #0B3D1C 100%)",
        }}
      />
      <AbsoluteFill
        style={{
          background: "radial-gradient(ellipse 70% 50% at 50% 50%, #2FA84F 0%, rgba(47,168,79,0) 70%)",
          opacity: 0.25 + 0.15 * breathe,
        }}
      />
      <AbsoluteFill style={{ opacity: 0.14, mixBlendMode: "overlay" }}>
        <svg width="1080" height="1920" viewBox="0 0 1080 1920">
          <filter id="green-static-grain" x="0" y="0" width="100%" height="100%">
            <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves={2} seed={seed} stitchTiles="stitch" />
            <feColorMatrix type="saturate" values="0" />
          </filter>
          <rect width="1080" height="1920" filter="url(#green-static-grain)" />
        </svg>
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          backgroundImage: "repeating-linear-gradient(0deg, rgba(0,0,0,0.18) 0px, rgba(0,0,0,0.18) 2px, rgba(0,0,0,0) 2px, rgba(0,0,0,0) 6px)",
          translate: `0px ${scanOffset}px`,
          opacity: 0.5,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          width: 1080,
          height: 240,
          top: rollY,
          background: "linear-gradient(180deg, rgba(168,230,184,0) 0%, rgba(168,230,184,0.06) 50%, rgba(168,230,184,0) 100%)",
        }}
      />
      <AbsoluteFill
        style={{
          background: "radial-gradient(ellipse 85% 75% at 50% 50%, rgba(0,0,0,0) 55%, rgba(4,26,12,0.65) 100%)",
        }}
      />
    </AbsoluteFill>
  );
};

export default GreenStatic;
